INSERT INTO `ai_recommendations` (`recommendation_id`, `asset_id`, `asset_age_years`, `total_repair_cost`, `repair_frequency`, `condition_score`, `recommendation`, `rationale`, `generated_at`, `generated_by_system`) VALUES (1,2,0.46,0.00,0,3,'MONITOR','This laptop is very new and currently in excellent condition. It is important to monitor its performance and usage closely over time, as it is a valuable asset to the office. Regularly observe its operation to ensure it continues to function effectively and to track any emerging needs.','2026-07-03 12:39:59',1);
INSERT INTO `ai_recommendations` (`recommendation_id`, `asset_id`, `asset_age_years`, `total_repair_cost`, `repair_frequency`, `condition_score`, `recommendation`, `rationale`, `generated_at`, `generated_by_system`) VALUES (2,2,0.46,0.00,0,3,'MONITOR','This laptop is very new, less than half a year old, and is currently in excellent, serviceable condition. With no recorded repair history or costs, it is performing as expected. Continue to observe its performance and ensure it remains in good working order.','2026-07-03 16:06:55',1);
INSERT INTO `ai_recommendations` (`recommendation_id`, `asset_id`, `asset_age_years`, `total_repair_cost`, `repair_frequency`, `condition_score`, `recommendation`, `rationale`, `generated_at`, `generated_by_system`) VALUES (3,2,0.46,0.00,0,3,'MAINTAIN','This laptop is very new and currently in excellent working condition. We recommend establishing a routine schedule for cleaning and software updates to keep it operating smoothly. Proactive care will help ensure its long-term reliability and performance.','2026-07-03 17:58:14',1);
INSERT INTO `ai_recommendations` (`recommendation_id`, `asset_id`, `asset_age_years`, `total_repair_cost`, `repair_frequency`, `condition_score`, `recommendation`, `rationale`, `generated_at`, `generated_by_system`) VALUES (4,25,0.47,0.00,0,3,'MAINTAIN','This laptop is very new and currently in excellent working condition. Regular care and preventative measures are important to keep it performing well. Please ensure it undergoes routine checks and is kept clean to maintain its current excellent state.','2026-07-05 20:27:00',1);
INSERT INTO `ai_recommendations` (`recommendation_id`, `asset_id`, `asset_age_years`, `total_repair_cost`, `repair_frequency`, `condition_score`, `recommendation`, `rationale`, `generated_at`, `generated_by_system`) VALUES (5,23,0.47,0.00,0,3,'MAINTAIN','This laptop is very new and in excellent working condition. To keep it performing optimally and extend its lifespan, ensure it receives regular cleaning, software updates, and basic preventative care. This proactive approach will help avoid future issues and maintain its efficiency for your office\'s needs.','2026-07-05 21:17:10',1);
INSERT INTO `ai_recommendations` (`recommendation_id`, `asset_id`, `asset_age_years`, `total_repair_cost`, `repair_frequency`, `condition_score`, `recommendation`, `rationale`, `generated_at`, `generated_by_system`) VALUES (6,3,0.45,0.00,0,3,'MAINTAIN','This printer is very new and currently in excellent, serviceable condition. Regular cleaning and routine checks will help ensure it continues to operate efficiently. Continue with standard care to maximize its lifespan and prevent future issues.','2026-07-05 22:41:45',1);
INSERT INTO `ai_recommendations` (`recommendation_id`, `asset_id`, `asset_age_years`, `total_repair_cost`, `repair_frequency`, `condition_score`, `recommendation`, `rationale`, `generated_at`, `generated_by_system`) VALUES (7,2,0.47,0.00,0,1,'REVIEW_FOR_DISPOSAL','This asset, a high-value laptop less than a year old, is recorded as unserviceable and already disposed without any repair history. It is highly unusual for such a new item to be disposed so quickly. Please investigate the circumstances of its early disposal and the lack of repair records to ensure proper procedures were followed for this valuable equipment.','2026-07-05 22:51:33',1);
