INSERT INTO `audit_log_digests` (`digest_id`, `digest`, `covered_entries`, `generated_at`, `generated_by_system`) VALUES (1,'The system recorded about eight actions over the past few days, primarily focused on asset management. Activities included creating new assets, categories, and records for maintenance and disposal, along with generating several AI recommendations for assets. It\'s worth noting that multiple actions, including asset creation and several AI recommendation generations, occurred during the very early morning hours, outside of typical business operations.',8,'2026-07-03 18:21:38',1);
INSERT INTO `audit_log_digests` (`digest_id`, `digest`, `covered_entries`, `generated_at`, `generated_by_system`) VALUES (2,'The system logged about 19 actions over the past few days, mainly involving asset creations, updates, and AI recommendations in the Assets module, along with user management in the Users module. All activity was performed by the \'admin\' user. A significant amount of recent activity occurred outside normal business hours, particularly late on July 5th and early on July 4th. On July 4th, the \'admin\' user created, updated, and then immediately deleted a \'test_staff2\' account within seconds, which might indicate a test or cleanup operation.',18,'2026-07-05 20:18:27',1);
INSERT INTO `audit_logs` (`log_id`, `user_id`, `action`, `module`, `target_id`, `target_type`, `details`, `ip_address`, `logged_at`) VALUES (1,1,'CATEGORY_CREATED','Categories',1,'category','Appliances',NULL,'2026-06-30 10:16:33');
