INSERT INTO `disposal_justifications` (`justification_id`, `disposal_id`, `justification`, `generated_at`, `generated_by_system`) VALUES (1,1,'The Refrigerator 7 cu.ft., bearing inventory tag COA-2026-011 and assigned to the Municipal Health Office, is being considered for disposal due to a critical failure of its compressor unit. This renders the appliance non-functional, and internal assessment indicates that repair would not be economically viable relative to the cost of a replacement unit.\n\nAn inspection conducted on 2026-06-15 confirmed that the compressor unit no longer builds pressure, consistent with a refrigerant leak. The unit has been completely non-functional for over three months. Additionally, the cabinet shows visible rust damage on the lower panel. While the asset is relatively new at 2.3 years and has no prior repair history, the extensive nature of the compressor failure, which is the core functional component, suggests that the cost of professional repair, including parts and labor for refrigerant system restoration, would likely approach or exceed its original unit value of PHP 16,500.00.\n\nGiven the irreparable damage to the primary functional component and the presence of refrigerants, which require specialized handling, the recommended disposal method is destruction. This method is appropriate to prevent potential unauthorized resale or repurposing of a permanently non-functional unit and ensures that all components, particularly hazardous materials like refrigerants, are managed in accordance with environmental regulations and applicable government property disposal regulations.','2026-07-03 16:00:48',1);
INSERT INTO `disposal_ledger` (`disposal_id`, `asset_id`, `reason`, `inspection_findings`, `recommended_method`, `disposal_status`, `inspection_date`, `approved_by`, `appraised_value`, `or_number`, `amount`, `recorded_by`, `is_deleted`, `deleted_at`, `deleted_by`, `delete_reason`, `created_at`, `updated_at`, `approval_status`, `requested_by`, `reviewed_by`, `reviewed_at`, `review_note`) VALUES (1,11,'Refrigerator compressor has failed and repair is not economically viable relative to replacement cost.','Compressor unit no longer builds pressure; refrigerant has leaked out; unit has been non-functional for over 3 months. Cabinet shows rust damage on lower panel.','SALE','PENDING','2026-06-15',NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,'2026-07-03 15:59:19','2026-09-27 07:53:25','APPROVED',NULL,NULL,NULL,NULL);
